三、讀取RFID 卡卡號 
我們從網路下載rfid-master.zip 後，解壓縮放入Arduino 程式libraries 的資料夾內，基本程式如下： 
#include <SPI.h> 
#include <MFRC522.h> // 引用程式庫 

#define RST_PIN A0 // 讀卡機的重置腳位 
#define SS_PIN 10 // 晶片選擇腳位 

MFRC522 mfrc522(SS_PIN, RST_PIN); // 建立MFRC522 物件 

void setup() { 
 Serial.begin(9600); 
 Serial.println("RFID reader is ready!"); 

 SPI.begin(); 
 mfrc522.PCD_Init(); // 初始化MFRC522 讀卡機模組 
} 

void loop() { 
 // 確認是否有新卡片 
 if (mfrc522.PICC_IsNewCardPresent() && mfrc522.PICC_ReadCardSerial()) { 
 byte *id = mfrc522.uid.uidByte; // 取得卡片的UID 
 byte idSize = mfrc522.uid.size; // 取得UID 的長度 

 Serial.print("PICC type: "); // 顯示卡片類型 
 // 根據卡片回應的SAK 值（mfrc522.uid.sak）判斷卡片類型 
 MFRC522::PICC_Type piccType = mfrc522.PICC_GetType(mfrc522.uid.sak); 
 Serial.println(mfrc522.PICC_GetTypeName(piccType)); 

 Serial.print("UID Size: "); // 顯示卡片的UID 長度值 
 Serial.println(idSize); 

 for (byte i = 0; i < idSize; i++) { // 逐一顯示UID 碼 
 Serial.print("id["); 
 Serial.print(i); 
 Serial.print("]: "); 
 Serial.println(id[i], HEX); // 以16 進位顯示UID 值 
 } 
 Serial.println(); 

 mfrc522.PICC_HaltA(); // 讓卡片進入停止模式 
 } 
} 



我們使用不同卡片來測試，發現卡片有4 組號碼與7 組號碼兩種模式，隨RFID 卡付贈的卡片、全聯卡為4 組號碼，悠遊卡、E 卡通為7 組號碼如上圖，每張卡片的卡號皆不同，RFID RC522 感應模組與Arduino UNO 連接如左圖。 

四、當卡片不正確時，就亮一秒紅燈。卡片正確，如果綠燈本來是熄滅的就變亮，本來是亮的就熄滅。 
 設計完成的線路圖及輸入程式如下所示︰ 


#include <SPI.h> 
#include <MFRC522.h> 
#define RST_PIN A0 
#define SS_PIN 10 
#define LED1 6 //紅色LED，代表卡片不正確 
#define LED2 7 //綠色LED，代表卡片正確 

//RFID 編碼結構(7 組16 進位+名稱)。 
struct RFIDTag { 
 byte uid[7]; 
 char *name; 
 }; 

//卡片和鈕扣的編碼。 
struct RFIDTag tags[] = { 
 {{0x04,0x25,0x55,0xFA,0xFC,0x48,0x81}, "2017 臺北世界大學運動會"}, 
 {{0x47,0x38,0x80,0xCB}, "白卡1 號"}, 
 {{0xBC,0x5D,0xE6,0xAB}, "圓形卡3 號"} 
}; 

byte totalTags = sizeof(tags) / sizeof(RFIDTag); 
 MFRC522 mfrc522(SS_PIN, RST_PIN); 

 void red() { 
 digitalWrite(LED1,HIGH); 
 delay(1000); 
 digitalWrite(LED1,LOW); 
 } 
 void green() { 
 if (digitalRead(LED2) == LOW) // 讀取 LED2 腳位 狀態 
 digitalWrite(LED2 , HIGH); // LED2 亮 

 else 
 digitalWrite(LED2 , LOW); // LED2 滅 
 } 

void setup() { 
 Serial.begin(9600); 
 Serial.println(); 
 Serial.print("size of RFIDTag:"); 
 Serial.println(sizeof(RFIDTag)); 
 Serial.print("size of tag:"); 
 Serial.println(sizeof(tags)); 
 Serial.println("RFID reader is ready!"); 

 SPI.begin(); 
 mfrc522.PCD_Init(); 
 pinMode(LED1,OUTPUT); 
 pinMode(LED2,OUTPUT); 
} 
 void loop() { 
 if (mfrc522.PICC_IsNewCardPresent() && mfrc522.PICC_ReadCardSerial()) { 
 byte *id = mfrc522.uid.uidByte; 
 byte idSize = mfrc522.uid.size; 
 bool foundTag = false; 

 Serial.println(); 
 for (byte i = 0; i < idSize; i++) { // 逐一顯示UID 碼 
 Serial.print(id[i], HEX); // 以16 進位顯示UID 值 
 Serial.print(" "); 
 } 
 Serial.println(); 

 for (byte i=0; i<totalTags; i++) { 
 if (memcmp(tags[i].uid, id, idSize) == 0) { 
 Serial.println(tags[i].name); 
 foundTag = true; 
 green(); 
 break; 
 //卡片正確就執行green() 
 } 
 } 
 if (!foundTag) { 
 Serial.println("Wrong card!"); 
 red(); 
 //卡片不正確就執行red() 
 } 
 mfrc522.PICC_HaltA(); 
 } 
 //停止卡片狀態。 
 } 

