二、RFID 卡啟燈模組程式 
 最後整合後所需輸入的程式如下︰ 
#include <SPI.h> 
#include <MFRC522.h> 
#include <EEPROM.h> 
#define RST_PIN A0 
#define SS_PIN 10 
#define LED1 6 //紅色LED 燈 
#define LED2 7 //綠色LED 燈 
#define LED3 8 //藍色LED 燈 
#define cleankey 4 //清除全部卡片接腳 
#define editkey 5 //增加卡片接腳 
int cleanpin; 

//RFID 編碼結構(8 組16 進位) 
struct RFIDTag 
{ 
 byte uid[8]; //設定每張卡片為8 組16 進位 
}; 

//卡片和鈕扣的編碼。 
struct RFIDTag tags[64]; //設定卡片張數為512/8=64 張 

byte totalTags = sizeof(tags) / sizeof(RFIDTag); 
 MFRC522 mfrc522(SS_PIN, RST_PIN); 

void red() //red 副程式 
{ 
 digitalWrite(LED1,HIGH); 
 delay(1000); 
 digitalWrite(LED1,LOW); 
} 

void green() //green 副程式 
{ 
 if (digitalRead(LED2) == LOW) // 讀取 LED2 腳位 狀態 
 digitalWrite(LED2 , HIGH); // LED2 亮 
 else 
 digitalWrite(LED2 , LOW); // LED2 滅 
} 

void setup() 
{ 
 Serial.begin(9600); //設定序列埠通訊速率 
 Serial.println(); 
 Serial.print("size of RFIDTag:"); 
 Serial.println(sizeof(RFIDTag)); 
 Serial.print("size of tag:"); 

 Serial.println(sizeof(tags)); 
 Serial.println("RFID reader is ready!"); 
 SPI.begin(); 
 mfrc522.PCD_Init(); 
 pinMode(LED1,OUTPUT); 
 pinMode(LED2,OUTPUT); 
 pinMode(LED3,OUTPUT); 
 pinMode(cleankey,INPUT); 
 pinMode(editkey,INPUT); 
 for (int i = 0; i < totalTags; i++) 
 for (int j = 0; j <= 7; j++) 
 tags[i].uid[j] = EEPROM.read(i*4+j); 
} 

void loop() 
{ 
 if (digitalRead(editkey) == 0) //增加卡片接腳 
 digitalWrite(LED3,LOW); 
 if (digitalRead(editkey) == 1) //增加卡片接腳 
 digitalWrite(LED3,HIGH); 
 if (digitalRead(cleankey) == 0) //清除卡片接腳 
 cleanpin = 0; 
 if ((digitalRead(cleankey) == 1) && (cleanpin == 0)) //清除鍵按下後放開才清除全部卡片資料 
 { 
 cleanpin = 1; 
 for (int i=0; i<totalTags; i++) 
 for (int j = 0; j <= 7; j++) 
 EEPROM.write(i*4+j,0); 

 for (int i=0; i<totalTags; i++) 
 for (int j = 0; j <= 7; j++) 
 tags[i].uid[j] = EEPROM.read(i*4+j); 

 for (int i=0; i<=10; i++) 
 { 
 digitalWrite(LED3,HIGH);delay(100);digitalWrite(LED3,LOW);delay(100); 
 } 
 } 

 //讀取卡片 
 if (mfrc522.PICC_IsNewCardPresent() && mfrc522.PICC_ReadCardSerial()) 
 { 
 byte *id = mfrc522.uid.uidByte; 
 byte idSize = mfrc522.uid.size; 
 bool foundTag = false; 
 Serial.println(); 
 for (int i = 0; i < idSize; i++) // 逐一顯示UID 碼 

 { 
 Serial.print(id[i], HEX); // 以16 進位顯示UID 值 
 Serial.print(" "); 
 } 
 Serial.println(); 
 for (int i=0; i<totalTags; i++) 
 { 
 if (memcmp(tags[i].uid, id, idSize) == 0) //讀到編碼資料執行green 副程式 
 { 
 foundTag = true; 
 green(); 
 break; 
 } 
 } 
 if (!foundTag) //如果卡片編碼錯誤就顯示錯誤 
 { 
 Serial.println("Wrong card!"); 
 red(); 
 if (digitalRead(editkey) == 1) 
 { 
 for (int i=0; i<totalTags; i++) 
 { 
 if (EEPROM.read(i*4) == 0) 
 { 
 for (int j = 0; j <= 7; j++) 
 EEPROM.write(i*4+j,id[j]); 
 for (int i=0; i<totalTags; i++) 
 for (int j = 0; j <= 7; j++) 
 tags[i].uid[j] = EEPROM.read(i*4+j); 
 for (int j = 0; j <= 7; j++) 
 { 
 Serial.print(EEPROM.read(i*4+j), HEX); 
 Serial.print(" "); 
 } 
 green(); 
 Serial.println(""); 
 Serial.println("Add Card Number"); 
 break; 
 } 
 } 
 } 
 } 
 mfrc522.PICC_HaltA(); //停止卡片狀態。 
 } 
} 

